func findByKey[T interface{ GetKey() string }](key string, ts ...T) (t T, _ bool) {
	return find(func(t T) bool { return t.GetKey() == key }, ts...)
}

func find[T any](match func(T) bool, ts ...T) (t T, _ bool) {
	for _, t := range ts {
		if match(t) {
			return t, true
		}
	}

	return t, false
}

func paginate[T any](params storage.QueryParams, less func(i, j int) bool, items ...T) (storage.ResultSet[T], error) {
	if len(items) == 0 {
		return storage.ResultSet[T]{}, nil
	}

	set := storage.ResultSet[T]{
		Results: items,
	}

	// sort by created_at and specified order
	sort.Slice(set.Results, func(i, j int) bool {
		if params.Order != storage.OrderAsc {
			i, j = j, i
		}

		return less(i, j)
	})

	// parse page token as an offset integer
	var offset int
	v, err := strconv.ParseInt(params.PageToken, 10, 64)
	if params.PageToken != "" && err != nil {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("pageToken is not valid: %q", params.PageToken)
	}

	offset = int(v)

	if offset >= len(set.Results) {
		return storage.ResultSet[T]{}, errs.ErrInvalidf("invalid offset: %d", offset)
	}

	// 0 means no limit on page size (all items from offset)
	if params.Limit == 0 {
		set.Results = set.Results[offset:]
		return set, nil
	}

	// ensure end of page does not exceed entire set
	end := offset + int(params.Limit)
	if end > len(set.Results) {
		end = len(set.Results)
	} else if end < len(set.Results) {
		// set next page token given there are more entries
		set.NextPageToken = fmt.Sprintf("%d", end)
	}

	// reduce results set to requested page
	set.Results = set.Results[offset:end]

	return set, nil
}
package common

import (
	"encoding/base64"
	"encoding/json"

	"go.flipt.io/flipt/errors"
	"go.uber.org/zap"
)

// decodePageToken is a utility function which determines the `PageToken` based on
// input.
func decodePageToken(logger *zap.Logger, pageToken string) (PageToken, error) {
	var token PageToken

	tok, err := base64.StdEncoding.DecodeString(pageToken)
	if err != nil {
		logger.Warn("invalid page token provided", zap.Error(err))
		return token, errors.ErrInvalidf("pageToken is not valid: %q", pageToken)
	}

	if err := json.Unmarshal(tok, &token); err != nil {
		logger.Warn("invalid page token provided", zap.Error(err))

		return token, errors.ErrInvalidf("pageToken is not valid: %q", pageToken)
	}

	return token, nil
}

// removeDuplicates is an inner utility function that will deduplicate a slice of strings.
func removeDuplicates(src []string) []string {
	allKeys := make(map[string]bool)

	dest := []string{}

	for _, item := range src {
		if _, value := allKeys[item]; !value {
			allKeys[item] = true
			dest = append(dest, item)
		}
	}

	return dest
}

// sanitizeSegmentKeys is a utility function that will transform segment keys into the right input.
func sanitizeSegmentKeys(segmentKey string, segmentKeys []string) []string {
	if len(segmentKeys) > 0 {
		return removeDuplicates(segmentKeys)
	} else if segmentKey != "" {
		return []string{segmentKey}
	}

	return nil
}
